class Solution {
    public long beautifulSubarrays(int[] nums){
        Map<Integer,Integer> frequency=new HashMap<>();
        frequency.put(0,1);
        int prefix=0;
        long answer=0;
        for(int value:nums){
            prefix^=value;
            answer+=frequency.getOrDefault(prefix,0);
            frequency.put(prefix,frequency.getOrDefault(prefix,0)+1);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun beautifulSubarrays(nums:IntArray):Long{
        val frequency=HashMap<Int,Int>();
        frequency[0]=1;
        var prefix=0;
        var answer=0L;
        for(value in nums){
            prefix=prefix xor value;
            answer+=frequency.getOrDefault(prefix,0);
            frequency[prefix]=frequency.getOrDefault(prefix,0)+1
        };
        return answer
    }
}

